    },
    {
      "id": "s5",
      "description": "If the best resolution is achieved at a boundary thickness (2mm or 10mm), run additional simulations at intermediate values around that optimum to confirm it is the true minimum and refine the recommendation."
    },
    {
      "id": "s6",
      "description": "Select the single material and plate thickness combination that achieves the best energy resolution while satisfying all constraints (hands-on maintenance compatibility and thickness range 2-10mm)."
    }
  ]
